function detectSchemeKey(name = '') {
  const lower = name.toLowerCase();
  if (lower.includes('samriddhi') || lower.includes('msy')) return 'msy';
  if (lower.includes('micro credit') || lower.includes('mcf')) return 'mcf';
  if (lower.includes('education') || lower.includes('शिक्षा') || lower.includes('విద్యా')) return 'education';
  if (lower.includes('term loan') || lower.includes('टर्म')) return 'term';
  if (lower.includes('green') || lower.includes('हरित') || lower.includes('గ్రీన్')) return 'green';
  if (lower.includes('laghu') || lower.includes('लघु') || lower.includes('చిన్న వ్యాపార')) return 'laghu';
  if (lower.includes('adhikariata') || lower.includes('अधिकारिता') || lower.includes('may')) return 'may';
  return null;
}

export function localizeSchemeName(scheme, lang = 'en') {
  if (!scheme) return '';
  const rawName = scheme.schemeName || scheme.name || '';
  const key = detectSchemeKey(rawName);
  if (key && SCHEME_TRANSLATIONS[key]?.[lang]) {
    return SCHEME_TRANSLATIONS[key][lang];
  }
  if (lang === 'hi' && scheme.nameHi) return scheme.nameHi;
  return rawName;
}

export function localizeSchemeDesc(scheme, lang = 'en') {
  if (!scheme) return '';
  if (lang === 'hi' && scheme.descriptionHi) return scheme.descriptionHi;
  if (lang === 'te') {
    const key = detectSchemeKey(scheme.schemeName || scheme.name);
    if (key === 'msy') return 'షెడ్యూల్డ్ కులాల మహిళా స్వయం సహాయక సంఘాలు మరియు మహిళా వ్యాపారవేత్తల కోసం ప్రత్యేక రాయితీ సూక్ష్మ రుణ పథకం.';
    if (key === 'mcf') return 'గ్రామీణ మరియు పట్టణ ప్రాంతాల్లో చిన్న వ్యాపారాల కోసం వేగవంతమైన రాయితీ సూక్ష్మ రుణాలు.';
    if (key === 'education') return 'భారతదేశంలో మరియు విదేశాలలో ఉన్నత వృత్తి మరియు సాంకేతిక విద్య కోసం ప్రత్యేక రాయితీ రుణాలు.';
    if (key === 'green') return 'ఈ-రిక్షాలు, సోలార్ మరియు పర్యావరణ అనుకూల వ్యాపారాలకు 90% వరకు రాయితీ నిధులు.';
    if (key === 'term') return 'ఉత్పత్తి, రవాణా మరియు సేవా యూనిట్ల ఏర్పాటు కోసం ₹50 లక్షల వరకు ప్రాజెక్ట్ రుణాలు.';
    if (key === 'laghu') return 'చిన్న వ్యాపారులు మరియు దుకాణదారుల మూలధన అవసరాల కోసం సులభమైన రాయితీ రుణాలు.';
  }
  return scheme.purpose || scheme.description || '';
}

/**
 * Localizes structured or unstructured Match Reasons generated by the Rule Engine
 */
export function localizeMatchReason(reason, t, lang = 'en') {
  if (!reason) return '';

  // 1. Income limit match
  if (reason.includes('Income within') || reason.includes('आधिकारिक सीमा')) {
    const limitMatch = reason.match(/₹([\d,]+)/g);
    const limit = limitMatch?.[0] || '₹5,00,000';
    const applicant = limitMatch?.[1] || '';
    if (lang === 'te') {
      return `కుటుంబ ఆదాయం అధికారిక పరిమితి ${limit} లోపు ఉంది ${applicant ? `(దరఖాస్తుదారు: ${applicant}/సంవత్సరానికి)` : ''}`;
    }
    if (lang === 'hi') {
      return `पारिवारिक आय आधिकारिक सीमा ${limit} के भीतर है ${applicant ? `(आवेदक: ${applicant}/वर्ष)` : ''}`;
    }
    if (lang === 'ta') {
      return `குடும்ப வருமானம் அதிகாரப்பூர்வ வரம்பான ${limit}க்குள் உள்ளது ${applicant ? `(விண்ணப்பதாரர்: ${applicant}/ஆண்டு)` : ''}`;
    }
    return reason;
  }

  // 2. Women entrepreneurs / MSY
  if (reason.includes('women entrepreneurs') || reason.includes('महिला उद्यमियों')) {
    if (lang === 'te') {
      return 'షెడ్యూల్డ్ కులాల మహిళా పారిశ్రామికవేత్తలు & SHGల కోసం 1.5% వడ్డీ ప్రోత్సాహకంతో ప్రత్యేకంగా రూపొందించబడింది';
    }
    if (lang === 'hi') {
      return 'अनुसूचित जाति की महिला उद्यमियों और स्वयं सहायता समूहों के लिए 1.5% ब्याज प्रोत्साहन के साथ विशेष योजना';
    }
    if (lang === 'ta') {
      return 'பட்டியல் சாதி பெண் தொழில்முனைவோர் மற்றும் மகளிர் குழுக்களுக்காக 1.5% வட்டி சலுகையுடன் பிரத்யேகமாக வடிவமைக்கப்பட்டது';
    }
    return reason;
  }

  // 3. Female student rebate
  if (reason.includes('female students') || reason.includes('महिला छात्रों')) {
    if (lang === 'te') {
      return 'NSFDC మార్గదర్శకాల ప్రకారం మహిళా విద్యార్థులకు 0.5% ప్రత్యేక వడ్డీ రాయితీకి అర్హులు';
    }
    if (lang === 'hi') {
      return 'एनएसएफडीसी दिशा-निर्देशों के तहत छात्राओं के लिए 0.5% विशेष ब्याज छूट हेतु पात्र';
    }
    return reason;
  }

  // 4. Approved professional/degree education
  if (reason.includes('degree programs') || reason.includes('professional') || reason.includes('डिग्री')) {
    if (lang === 'te') {
      return 'ఆమోదించబడిన వృత్తి, సాంకేతిక లేదా విదేశీ డిగ్రీ కోర్సులకు నేరుగా సరిపోలుతుంది';
    }
    if (lang === 'hi') {
      return 'मान्यता प्राप्त व्यावसायिक, तकनीकी अथवा विदेश अध्ययन डिग्री कार्यक्रमों के लिए उपयुक्त';
    }
    return reason;
  }

  // 5. Project Type match
  if (reason.includes('Project type') || reason.includes('परियोजना प्रकार')) {
    if (lang === 'te') {
      return 'ఎంచుకున్న వ్యాపార రంగం అధికారిక మార్గదర్శకాల ప్రకారం అర్హత కలిగిన కార్యకలాపాలకు సరిపోలుతుంది';
    }
    if (lang === 'hi') {
      return 'परियोजना क्षेत्र आधिकारिक दिशा-निर्देशों के तहत पात्र गतिविधियों से मेल खाता है';
    }
    return reason;
  }

  // 6. Green Energy
  if (reason.includes('clean-energy') || reason.includes('हरित')) {
    if (lang === 'te') {
      return '90% ప్రాజెక్ట్ వ్యయ సహాయంతో ప్రాధాన్యత కలిగిన క్లీన్ ఎనర్జీ / సోలార్ విండో';
    }
    if (lang === 'hi') {
      return '90% परियोजना लागत कवरेज के साथ प्राथमिकता प्राप्त स्वच्छ ऊर्जा / सौर विंडो';
    }
    return reason;
  }

  // 7. Micro Finance
  if (reason.includes('micro-finance') || reason.includes('सूक्ष्म ऋण')) {
    if (lang === 'te') {
      return 'కనిష్ట హామీతో వేగవంతమైన సూక్ష్మ ఆర్థిక సహాయ విండో';
    }
    if (lang === 'hi') {
      return 'न्यूनतम संपार्श्विक और आसान प्रक्रिया के साथ फास्ट-ट्रैक सूक्ष्म वित्त विंडो';
    }
    return reason;
  }

  // 8. Amount within limit
  if (reason.includes('within scheme maximum limit') || reason.includes('अधिकतम सीमा के भीतर')) {
    const amounts = reason.match(/₹[\d,]+/g);
    const cost = amounts?.[0] || '';
    const max = amounts?.[1] || '';
    if (lang === 'te') {
      return `కోరిన మొత్తం ${cost} పథకం గరిష్ట పరిమితి ${max} లోపు ఉంది`;
    }
    if (lang === 'hi') {
      return `अनुरोधित राशि ${cost} योजना की अधिकतम सीमा ${max} के भीतर है`;
    }
    return reason;
  }

  // 9. Concessional rate
  if (reason.includes('Concessional subsidized interest rate') || reason.includes('रियायती ब्याज दर')) {
    const rateMatch = reason.match(/([\d.]+)%/);
    const rate = rateMatch?.[1] || '';
    if (lang === 'te') {
      return `వాణిజ్య బ్యాంకుల కంటే గణనీయంగా తక్కువైన ${rate}% రాయితీ వడ్డీ రేటు`;
    }
    if (lang === 'hi') {
      return `वाणिज्यिक बैंकों की तुलना में काफी कम ${rate}% वार्षिक रियायती ब्याज दर`;
    }
    return reason;
  }

  // 10. Moratorium
  if (reason.includes('moratorium grace period') || reason.includes('मोरेटोरियम')) {
    const monthMatch = reason.match(/(\d+)-month/);
    const months = monthMatch?.[1] || '';
    if (lang === 'te') {
      return `అసలు చెల్లింపు ప్రారంభం కావడానికి ముందు ${months} నెలల మొరటోరియం (మినహాయింపు కాలం)`;
    }
    if (lang === 'hi') {
      return `मूलधन पुनर्भुगतान शुरू होने से पहले ${months} महीने की मोरेटोरियम छूट अवधि`;
    }
    return reason;
  }

  // 11. Agencies
  if (reason.includes('Disbursed through') || reason.includes('संवितरित')) {
    if (lang === 'te') {
      return 'దేశవ్యాప్తంగా అధీకృత భాగస్వామ్య బ్యాంకులు మరియు రాష్ట్ర కార్పొరేషన్ శాఖల ద్వారా విడుదల';
    }
    if (lang === 'hi') {
      return 'देशभर में अधिकृत चैनल पार्टनर शाखाओं के माध्यम से संवितरित';
    }
    return reason;
  }

  return reason;
}

/**
 * Localizes document titles across the application
 */
export function localizeDocumentName(doc, t) {
  if (!doc) return '';
  const d = String(doc).toLowerCase();
  if (d.includes('caste') || d.includes('जाति') || d.includes('కుల')) {
    return t('guidance.doc1Title', 'Caste Certificate (SC)');
  }
  if (d.includes('income') || d.includes('आय') || d.includes('ఆదాయ')) {
    return t('guidance.doc2Title', 'Income Certificate (≤ ₹5L/yr)');
  }
  if (d.includes('aadhaar') || d.includes('आधार') || d.includes('ఆధార్')) {
    return t('guidance.doc3Title', 'Aadhaar Card (DBT-Linked)');
  }
  if (d.includes('project report') || d.includes('dpr') || d.includes('डीपीआर') || d.includes('ప్రాజెక్టు')) {
    return t('guidance.doc4Title', 'Detailed Project Report (DPR)');
  }
  if (d.includes('quotation') || d.includes('invoice') || d.includes('कोटेशन') || d.includes('కొటేషన్')) {
    return t('guidance.doc5Title', 'Equipment / Vehicle Quotation');
  }
  if (d.includes('admission') || d.includes('शिक्षा') || d.includes('college') || d.includes('విద్యా')) {
    return t('guidance.doc6Title', 'Admission Letter & Fee Schedule');
  }
  if (d.includes('passbook') || d.includes('cheque') || d.includes('पासबुक') || d.includes('పాస్‌బుక్')) {
    return t('track.docs.bankPassbook', 'Bank Passbook / Cancelled Cheque');
  }
  return doc;
}
